const root=fileURLToPath(new URL('../',import.meta.url)),intake=process.argv[2];

const readJSON=p=>JSON.parse(fs.readFileSync(p,'utf8').replace(/^\uFEFF/,''));
const sha=b=>crypto.createHash('sha256').update(b).digest('hex');
const round=n=>Math.abs(n)<1e-12?0:Number(n.toFixed(9));
const emitted=new Set();
const put=(name,data)=>{emitted.add(name);const p=path.join(root,name);fs.mkdirSync(path.dirname(p),{recursive:true});fs.writeFileSync(p,data);return {url:name,sha256:sha(data),bytes:data.length};};
const json=(name,data)=>put(name,Buffer.from(JSON.stringify(data)+'\n'));
const packed=(name,data)=>put(name,gzipSync(Buffer.from(JSON.stringify(data)),{level:9}));
const loadPacked=n=>JSON.parse(gunzipSync(fs.readFileSync(path.join(root,n))));
const map=loadPacked('source/surface.map.json.gz');
const silo=loadPacked('source/coldwell-complex.game-mesh.json.gz'),infill=loadPacked('source/surface-infill.mesh.json.gz');
const prototypes={},materials={},entries=[],sourceCounts={silo:silo.metrics,infill:infill.metrics,terrain:{},edges:Object.keys(map.edges).length,props:map.props.length,trees:map.props.filter(p=>p.kind.startsWith('tree-')).length,roofCells:Object.keys(map.upper[0]).length};
for(const row of map.terrain)for(const k of row)sourceCounts.terrain[k]=(sourceCounts.terrain[k]||0)+1;
const boundsOf=(positions)=>{const min=[Infinity,Infinity,Infinity],max=[-Infinity,-Infinity,-Infinity];for(let i=0;i<positions.length;i++) {const axis=i%3;min[axis]=Math.min(min[axis],positions[i]);max[axis]=Math.max(max[axis],positions[i]);}return {min,max};};
const union=(a,b)=>({min:a.min.map((v,i)=>Math.min(v,b.min[i])),max:a.max.map((v,i)=>Math.max(v,b.max[i]))});
function geometryData(g){return {positions:Array.from(g.attributes.position.array,round),normals:Array.from(g.attributes.normal.array,round),uvs:g.attributes.uv?Array.from(g.attributes.uv.array,round):Array(g.attributes.position.count*2).fill(0),...(g.index?{indices:Array.from(g.index.array)}:{})};}
function mergeRoot(group,prefix){
 group.updateMatrixWorld(true);const parts=new Map();
 group.traverse(m=>{if(!m.isMesh)return;const id=m.material.name;if(!id)throw Error('Unnamed source material');let g=m.geometry.index?m.geometry.toNonIndexed():m.geometry.clone();g.applyMatrix4(m.matrixWorld);
  if(!parts.has(id))parts.set(id,{positions:[],normals:[],uvs:[]});const b=parts.get(id),d=geometryData(g);b.positions.push(...d.positions);b.normals.push(...d.normals);b.uvs.push(...d.uvs);g.dispose();});
 return [...parts].map(([material,g],i)=>{const id=prefix+'-'+i;prototypes[id]={...g,bounds:boundsOf(g.positions)};return {geometry:id,material};});
}
// Preserve exact source material patches generated by the original cargo factory.
const dummyTexture=name=>{const t=new T.Texture({width:1024,height:1024});t.name=name;return t;};
const cargo=createCargoLibrary(dummyTexture('original'),dummyTexture('cargo'));
function cargoMaterial(m){
 const shader={fragmentShader:'#include <map_fragment>',vertexShader:''};m.onBeforeCompile(shader,null);
 const recipe={type:'cargo',color:m.color.toArray(),roughness:m.roughness,metalness:m.metalness,side:m.side,patch:shader.fragmentShader,...(m.map?{texture:m.map.name,offset:m.map.offset.toArray(),repeat:m.map.repeat.toArray()}:{} )};
 const id='cargo:'+sha(Buffer.from(JSON.stringify(recipe))).slice(0,16);materials[id]=recipe;m.name=id;
}
const plantMaterials=Object.fromEntries([...Object.keys(BIOME_PAINT),'grey'].map(id=>{const m=new T.MeshStandardMaterial();m.name='biome:'+id;return [id,m];}));
const plants=createBiomePlantFactory(plantMaterials),shapeGeometry=environmentGeometries();
for(const name of ['box','cylinder'])prototypes['shape:'+name]={...geometryData(shapeGeometry[name]),bounds:{min:[-.5,-.5,-.5],max:[.5,.5,.5]}};
const surfaceGroups=new Map(),world=buildWorld(map);if(world.diagnostics.length)throw Error(JSON.stringify(world.diagnostics));
const cargoPropKeys=new Set(cargoPlacements(map).map(p=>`prop:${p.x},${p.y},${p.z||0}:${p.kind}`));
function surfaceInstance(sourceId,category,parts,transform){
 const center=new T.Vector3().setFromMatrixPosition(transform),block=[Math.floor(center.x/24),Math.floor(center.z/24)];
 const key=category+'-'+block.join('-');if(!surfaceGroups.has(key))surfaceGroups.set(key,{id:'surface-'+key,kind:'surface',frame:'canonical',category,block,batches:new Map(),bounds:null,sourceIds:new Set()});const group=surfaceGroups.get(key);group.sourceIds.add(sourceId);
 for(const part of parts){const d=prototypes[part.geometry],box=new T.Box3(new T.Vector3(...d.bounds.min),new T.Vector3(...d.bounds.max)).applyMatrix4(transform),bounds={min:box.min.toArray(),max:box.max.toArray()};group.bounds=group.bounds?union(group.bounds,bounds):bounds;
  const k=part.geometry+'|'+part.material;if(!group.batches.has(k))group.batches.set(k,{...part,matrices:[],sourceIds:[]});const b=group.batches.get(k);b.matrices.push(transform.toArray().map(round));b.sourceIds.push(sourceId);}
}
const transform=(center,size=[1,1,1],rotation=[0,0,0],yaw=0)=>new T.Matrix4().compose(new T.Vector3(...center),new T.Quaternion().setFromEuler(new T.Euler(...rotation)).premultiply(new T.Quaternion().setFromAxisAngle(new T.Vector3(0,1,0),yaw)),new T.Vector3(...size));
const doorVisuals=new Map();
for(const b of environmentVisuals(world,map,{biomes:true})){
 if(b.source.prop&&cargoPropKeys.has(b.source.prop))continue;
 if(b.source.edge&&b.id.includes(':door')){if(!doorVisuals.has(b.source.edge))doorVisuals.set(b.source.edge,[]);doorVisuals.get(b.source.edge).push(b);continue;}
 const kind=materialKind(b),ground=b.kind==='floor'&&!b.source.z&&['grass','sand'].includes(kind),material=ground?'ground:map':'base:'+kind;
 if(!materials[material])materials[material]=ground?{type:'map-ground'}:{type:'pixels',...surfacePixels(kind)};
 // Typed pixel arrays become plain arrays for portable JSON.
 if(materials[material].data&&!Array.isArray(materials[material].data))materials[material].data=Array.from(materials[material].data);
 const category=b.kind==='floor'&&b.source.z?'roof':b.kind==='floor'?'ground':'structure';
 surfaceInstance(b.id,category,[{geometry:'shape:'+(b.shape||'box'),material}],transform(b.center.map((v,i)=>v+FRAMES.site[i]),b.size,b.rotation,b.yaw));
}
const plantPrototypes=new Map();
for(const p of map.props.filter(p=>p.kind.startsWith('tree-'))){
 const family=biomeFamilyAt(map,p.x,p.y,p.z||0),id=BIOME_FAMILIES[family].trees[p.kind.includes('pine')?1:0],variant=Math.floor(groundHash(p.x,p.y,biomeSeed(map))*3),mature=p.kind.endsWith('-large'),key=[id,variant,mature].join('-');
 if(!plantPrototypes.has(key)){const model=plants.create(id,{variant,mature});plantPrototypes.set(key,mergeRoot(model,'plant-'+key));}
 const parts=plantPrototypes.get(key),matrix=transform([p.x+.5,46.64+(p.z||0)*2.12,p.y+.5],[1,1,1],[0,p.rotated?-Math.PI/2:0,0]);
 for(const part of parts){const canopy=part.material!=='biome:bark';materials[part.material]={type:'biome',paint:part.material.slice(6)};surfaceInstance(`prop:${p.x},${p.y},${p.z||0}:${p.kind}`,canopy?'canopy':'tree-trunk',[part],matrix);}
}
const cargoPrototypes=new Map();
for(const p of cargoPlacements(map)){
 const {skin,label,id}=cargoFinish(p);
 if(!cargoPrototypes.has(id)){const model=cargo.build(p.form,skin,label);model.root.traverse(m=>{if(m.isMesh)cargoMaterial(m.material);});cargoPrototypes.set(id,mergeRoot(model.root,'cargo-'+id));}
 surfaceInstance(`prop:${p.x},${p.y},${p.z||0}:${p.kind}`,'cargo',cargoPrototypes.get(id),transform([p.x+.5,46.64+(p.z||0)*2.12,p.y+.5],[1,1,1],[0,p.rotated?-Math.PI/2:0,0]));
}
for(const g of surfaceGroups.values()){
 const batches=[...g.batches.values()],data={version:1,batches},count=batches.reduce((n,b)=>n+(prototypes[b.geometry].indices?.length??prototypes[b.geometry].positions.length/3)/3*b.matrices.length,0);
 entries.push({id:g.id,kind:g.kind,frame:g.frame,category:g.category,block:g.block,bounds:canonicalBounds('canonical',{min:{x:g.bounds.min[0],h:g.bounds.min[1],y:g.bounds.min[2]},max:{x:g.bounds.max[0],h:g.bounds.max[1],y:g.bounds.max[2]}}),sourceIds:[...g.sourceIds],triangles:count,batches:batches.length,...packed('chunks/'+g.id+'.json.gz',data)});
}
const staticGroups=new Map(),clipStats={sourceTriangles:0,derivedTriangles:0,sourceArea:0,derivedArea:0};
const triangleArea=(a,b,c)=>new T.Vector3(b[0]-a[0],b[1]-a[1],b[2]-a[2]).cross(new T.Vector3(c[0]-a[0],c[1]-a[1],c[2]-a[2])).length()/2;
function clip(poly,axis,edge,sign){const result=[];for(let i=0;i<poly.length;i++){const a=poly[i],b=poly[(i+1)%poly.length],da=sign*(a[axis]-edge),db=sign*(b[axis]-edge),insideA=da>=-1e-9,insideB=db>=-1e-9;if(insideA)result.push(a);if(insideA!==insideB){const t=da/(da-db);result.push(a.map((v,j)=>v+(b[j]-v)*t));}}return result;}
function addStatic(data,frame){const offset=FRAMES[frame];for(const [index,b]of data.batches.entries())for(let v=0;v<b.positions.length/3;v+=3){
 const tri=[0,1,2].map(i=>[...b.positions.slice((v+i)*3,(v+i)*3+3),...b.normals.slice((v+i)*3,(v+i)*3+3),...b.uvs.slice((v+i)*2,(v+i)*2+2)]),area=triangleArea(...tri);clipStats.sourceTriangles++;clipStats.sourceArea+=area;
 const xs=tri.map(a=>a[0]+offset[0]),zs=tri.map(a=>a[2]+offset[2]),x0=Math.floor(Math.min(...xs)/24),x1=Math.floor((Math.max(...xs)-1e-9)/24),z0=Math.floor(Math.min(...zs)/24),z1=Math.floor((Math.max(...zs)-1e-9)/24);
 const ys=tri.map(a=>a[1]+offset[1]),h0=Math.floor((Math.min(...ys)+1e-9)/2.12),h1=Math.floor((Math.max(...ys)-1e-9)/2.12);
 for(let x=x0;x<=Math.max(x0,x1);x++)for(let z=z0;z<=Math.max(z0,z1);z++)for(let h=h0;h<=Math.max(h0,h1);h++){
  let poly=tri;for(const [axis,edge,sign]of [[0,x*24-offset[0],1],[0,(x+1)*24-offset[0],-1],[2,z*24-offset[2],1],[2,(z+1)*24-offset[2],-1],[1,h*2.12-offset[1],1],[1,(h+1)*2.12-offset[1],-1]]){poly=clip(poly,axis,edge,sign);if(poly.length<3)break;}
  if(poly.length<3)continue;const key=[frame,b.zone,b.level,b.highLevel,x,z,'h'+h].join('-');if(!staticGroups.has(key))staticGroups.set(key,{id:key,frame,zone:b.zone,level:b.level,highLevel:b.highLevel,block:[x,z],renderHeightBand:{min:round(h*2.12),max:round((h+1)*2.12)},batches:new Map()});const group=staticGroups.get(key),bk=index;
  if(!group.batches.has(bk))group.batches.set(bk,{...Object.fromEntries(Object.entries(b).filter(([k])=>!['positions','normals','uvs'].includes(k))),sourceBatch:index,positions:[],normals:[],uvs:[]});const out=group.batches.get(bk);
  for(let i=1;i<poly.length-1;i++){const vs=[poly[0],poly[i],poly[i+1]],a=triangleArea(...vs);if(a<1e-12)continue;for(const q of vs){out.positions.push(...q.slice(0,3).map(round));out.normals.push(...q.slice(3,6).map(round));out.uvs.push(...q.slice(6,8).map(round));}clipStats.derivedTriangles++;clipStats.derivedArea+=a;}
 }
 }}
addStatic(silo,'silo');addStatic(infill,'site');
function siloData(id,batches,rigs,bounds){const triangles=batches.reduce((n,b)=>n+b.positions.length/9,0)+rigs.reduce((n,r)=>n+r.batches.reduce((n,b)=>n+b.positions.length/9,0),0);return {schema:silo.schema,version:1,asset:{id},lod:'game',uvMode:'metres',metresPerUnit:1,nativeToWorld:silo.nativeToWorld,bounds,metrics:{triangles,batches:batches.length+rigs.reduce((n,r)=>n+r.batches.length,0),rigs:rigs.length},batches,rigs};}
for(const g of staticGroups.values()){
 const batches=[...g.batches.values()].filter(b=>b.positions.length);if(!batches.length)continue;
 const bounds=batches.map(b=>boundsOf(b.positions)).reduce(union),data=siloData(g.id,batches,[],bounds);
 entries.push({id:g.id,kind:'silo',frame:g.frame,zone:g.zone,level:g.level,highLevel:g.highLevel,block:g.block,renderHeightBand:g.renderHeightBand,bounds:canonicalBounds(g.frame,bounds),kinds:[...new Set(batches.map(b=>b.kind))],sourceBatches:batches.map(b=>b.sourceBatch),triangles:data.metrics.triangles,batches:batches.length,...packed('chunks/'+g.id+'.json.gz',data)});
}
const rigDescriptors=[];
function addRig(d,frame){
 const data=siloData(d.id,[],[d],silo.bounds),model=createSiloModel(T,data);model.root.position.fromArray(FRAMES[frame]);model.setRigPose(d.id,0);let box=new T.Box3().setFromObject(model.root,true);
 if(d.kind==='door'){
  if(JSON.stringify(d.axis)!=='[0,1,0]')throw Error('Unreviewed door axis');let radius=0;const group=model.rigs[0].group;group.updateMatrixWorld(true);const pivot=new T.Vector3(...d.pivot).add(new T.Vector3(...FRAMES[frame]));group.traverse(m=>{if(!m.isMesh)return;const p=m.geometry.attributes.position;for(let i=0;i<p.count;i++){const v=new T.Vector3().fromBufferAttribute(p,i).applyMatrix4(m.matrixWorld);radius=Math.max(radius,Math.hypot(v.x-pivot.x,v.z-pivot.z));}});box.min.x=pivot.x-radius;box.max.x=pivot.x+radius;box.min.z=pivot.z-radius;box.max.z=pivot.z+radius;
 }else{model.setRigPose(d.id,d.maximum);box.union(new T.Box3().setFromObject(model.root,true));}
 const bounds={min:{x:box.min.x,y:box.min.z,h:box.min.y},max:{x:box.max.x,y:box.max.z,h:box.max.y}};model.dispose();
 const descriptor={...Object.fromEntries(Object.entries(d).filter(([k])=>k!=='batches')),frame,bounds};rigDescriptors.push(descriptor);
 entries.push({id:'rig-'+d.id,rigId:d.id,kind:'silo',frame,zone:frame==='site'?'surface-door':d.batches[0].zone,level:d.level,highLevel:d.highLevel,bounds,triangles:data.metrics.triangles,batches:data.metrics.batches,...packed('chunks/rig-'+d.id.replaceAll(':','_')+'.json.gz',data)});
}
for(const d of silo.rigs)addRig(d,'silo');
for(const [edge,visuals]of doorVisuals){
 const leaf=visuals.find(b=>b.id.endsWith(':door'));if(!leaf)throw Error('Door leaf absent');const east=edge.startsWith('e:'),pivot=leaf.center.map((v,i)=>v-(i===0&&!east?leaf.size[0]/2:i===2&&east?leaf.size[2]/2:i===1?leaf.size[1]/2:0));
 const batches=visuals.map(b=>{let geo=shapeGeometry[b.shape||'box'].index?shapeGeometry[b.shape||'box'].toNonIndexed():shapeGeometry[b.shape||'box'].clone();geo.applyMatrix4(transform(b.center.map((v,i)=>v-pivot[i]),b.size,b.rotation,b.yaw));const g=geometryData(geo);geo.dispose();return {zone:'surface-door',kind:'door',level:22,highLevel:23,material:b===leaf?'steel':'dark',positions:g.positions,normals:g.normals,uvs:g.uvs};});
 addRig({id:'surface-door:'+edge,sourceEdge:edge,kind:'door',level:22,highLevel:23,pivot,yaw:0,axis:[0,1,0],maximum:90,swingSign:1,batches},'site');
}
if(Math.abs(clipStats.sourceArea-clipStats.derivedArea)>1e-5)throw Error('Partition area changed: '+JSON.stringify(clipStats));
const weights={cells:[]};for(let y=-1;y<=240;y++)for(let x=-1;x<=240;x++)weights.cells.push(biomeMixAt(map,x,y,0));
const manifest={schema:'farmyard-coldwell-art',version:1,source:SOURCE,metresPerUnit:1,coordinates:{canonical:'{x,y,h}; Three(x,h,y)',frames:FRAMES,companionAnchors:'already canonical; no additional offset'},metrics:{...sourceCounts,partition:clipStats},floors:Array.from({length:23},(_,index)=>({id:'coldwell-datum-'+String(index).padStart(2,'0'),index,h:round(index*2.12),label:index===22?'G':'B'+(22-index)})),rigs:rigDescriptors,
 textures:Object.fromEntries(fs.readdirSync(path.join(root,'textures')).sort().map(n=>{const b=fs.readFileSync(path.join(root,'textures',n));return [n.slice(0,-4),{url:'textures/'+n,sha256:sha(b),bytes:b.length}];})),
 prototypes:packed('surface-prototypes.json.gz',{version:1,geometries:prototypes,materials}),groundWeights:packed('ground-weights.json.gz',weights),
 semantics:packed('semantics.json.gz',{version:1,silo:{frame:'silo',...silo.semantics},infill:{frame:'site',...infill.semantics},surface:{frame:'site',map:'source/surface.map.rle.json',layout:readJSON(path.join(root,'source/site-layout.json'))},companion:readJSON(path.join(root,'source/silo-companion.json'))}),
 entries:entries.sort((a,b)=>a.id.localeCompare(b.id,'en'))};
json('manifest.json',manifest);
// Remove only obsolete files from this compiler's verified flat output directory.
const chunkDirectory=path.resolve(root,'chunks');if(!chunkDirectory.startsWith(path.resolve(root)+path.sep))throw Error('Unsafe chunk output');
for(const file of fs.readdirSync(chunkDirectory)){const relative='chunks/'+file;if(file.endsWith('.json.gz')&&!emitted.has(relative))fs.unlinkSync(path.join(chunkDirectory,file));}
for(const g of new Set(Object.values(shapeGeometry)))g.dispose();plants.dispose();for(const m of Object.values(plantMaterials))m.dispose();cargo.dispose();
console.log(JSON.stringify({entries:entries.length,rigs:rigDescriptors.length,prototypes:Object.keys(prototypes).length,triangles:entries.reduce((n,e)=>n+e.triangles,0),partition:clipStats}));
